export const MUSIC_READS:NewsArticle[]=drafts.map(a=>({slug:a.slug,kind:"feature",section:"Biography",title:a.title,dek:a.dek,grades:"Grades 4–8",publishedOn:"2026-10-22",photo:{wikipediaTitle:a.wiki,alt:"Photograph of "+a.name},sources:a.sources.map(url=>({name:new URL(url).hostname,url})),body:a.body.split(/\n\n/).map(t=>t.startsWith("## ")?{kind:"h" as const,text:t.slice(3)}:{kind:"p" as const,text:t}),words:a.words.map(([word,meaning])=>({word,meaning})),questions:a.qa.map(([question,correct,...wrong],i)=>{const k=[3,1,0,2,3][i];const arr=[...wrong];arr.splice(k,0,correct);return{question,options:arr as NewsQuestion["options"],correct:letters[k]};})}));